def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    opp_def_total = 0
    for a in opp:
        if a == 'D':
            opp_def_total += 1

    my_def_total = 0
    for a in me:
        if a == 'D':
            my_def_total += 1

    start = n - 5
    if start < 0:
        start = 0
    opp_def5 = 0
    for i in range(start, n):
        if opp[i] == 'D':
            opp_def5 += 1

    start = n - 10
    if start < 0:
        start = 0
    opp_def10 = 0
    for i in range(start, n):
        if opp[i] == 'D':
            opp_def10 += 1

    od = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            od += 1
        else:
            break

    after_c = 0
    start = n - 20
    if start < 1:
        start = 1
    for i in range(start, n):
        if me[i - 1] == 'C' and opp[i] == 'D':
            after_c += 1

    un = 0
    pun = 0
    start = n - 60
    if start < 0:
        start = 0
    for i in range(start, n - 1):
        if me[i] == 'D':
            if opp[i + 1] == 'D':
                pun += 1
            elif opp[i] == 'C':
                un += 1

    if after_c >= 5 or (opp_def_total >= max(8, n // 2) and opp_def5 >= 4):
        return 'D'

    if n >= 2 and opp_def_total == n:
        return 'D'

    if un >= 2 and pun == 0 and opp_def5 <= 2 and opp_def_total <= max(8, n // 3):
        return 'D'

    if un >= 3 and pun * 3 <= un and opp_def5 <= 3 and opp_def_total <= max(10, n // 2):
        return 'D'

    if n >= 85 and un >= 1 and pun == 0 and opp_def5 <= 2 and opp_def_total <= max(10, n // 2):
        return 'D'

    if n >= 2 and me[-2] == 'D' and opp[-2] == 'C' and opp[-1] == 'C' and pun == 0 and opp_def5 <= 2 and un >= 1:
        return 'D'

    if (n == 50 or n == 80) and last_opp == 'C' and last_me == 'C' and un == 0 and pun == 0 and after_c <= 2 and opp_def_total <= max(3, n // 20):
        return 'D'

    if n == 97 or n == 98:
        if last_opp == 'C' and opp_def5 <= 1 and after_c <= 2 and un == 0 and pun == 0:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_def_total <= max(6, n // 2) and od <= 4:
                return 'C'
            return 'D'

        if od == 1:
            if n >= 2 and me[-2] == 'D':
                return 'C'
            if opp_def5 <= 1 and opp_def10 <= 2 and after_c <= 2:
                return 'C'
            return 'D'

        return 'D'

    return 'C'
